/// One flat table, type-erased so the gates can walk them by name.
///
/// The game never touches this — it indexes the concrete `[u8; N]` statics
/// directly. It exists because Rust cannot look a static up by name and two
/// consumers need to: the parity test that diffs these tables against the
/// TypeScript build, and the tuning index.
#[derive(Clone, Copy, Debug)]
pub enum Table {
    U8(&'static [u8]),
    U16(&'static [u16]),
    U32(&'static [u32]),
    F32(&'static [f32]),
}

impl Table {
    pub fn len(&self) -> usize {
        match self {
            Table::U8(v) => v.len(),
            Table::U16(v) => v.len(),
            Table::U32(v) => v.len(),
            Table::F32(v) => v.len(),
        }
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// The slot as an `f64`, which is lossless for every width used here.
    pub fn get(&self, i: usize) -> f64 {
        match self {
            Table::U8(v) => v[i] as f64,
            Table::U16(v) => v[i] as f64,
            Table::U32(v) => v[i] as f64,
            Table::F32(v) => v[i] as f64,
        }
    }

    pub fn kind(&self) -> &'static str {
        match self {
            Table::U8(_) => "u8",
            Table::U16(_) => "u16",
            Table::U32(_) => "u32",
            Table::F32(_) => "f32",
        }
    }
}

/// Every module's tables, for the gates. `(module, name, table)`.
pub fn all_tables() -> Vec<(&'static str, &'static str, Table)> {
    let mut out = Vec::new();
    for (n, t) in blocks::BLOCK_TABLES {
        out.push(("blocks", *n, *t));
    }
    for (n, t) in items::ITEM_TABLES {
        out.push(("items", *n, *t));
    }
    for (n, t) in mobs::MOB_TABLES {
        out.push(("mobs", *n, *t));
    }
    for (n, t) in sprites::SPRITE_TABLES {
        out.push(("sprites", *n, *t));
    }
    for (n, t) in structs::STRUCT_TABLES {
        out.push(("structs", *n, *t));
    }
    for (n, t) in worldgen::FEATURE_TABLES {
        out.push(("worldgen", *n, *t));
    }
    out
}

